const insertLedgerJournalBatch = `-- name: InsertLedgerJournalBatch :many
INSERT INTO ledger_journal (owner_kind, owner_id, entry_id, at, ref_type, activity, amount, first_party_id, second_party_id, context_id, context_type)
SELECT $1::text, $2::bigint,
       unnest($3::bigint[]), unnest($4::text[])::timestamptz,
       unnest($5::text[]), unnest($6::text[]),
       unnest($7::float8[]), unnest($8::bigint[]),
       unnest($9::bigint[]), unnest($10::bigint[]),
       unnest($11::text[])
ON CONFLICT DO NOTHING
RETURNING at
`

type InsertLedgerJournalBatchParams struct {
	OwnerKind     string    `json:"owner_kind"`
	OwnerID       int64     `json:"owner_id"`
	EntryIds      []int64   `json:"entry_ids"`
	Ats           []string  `json:"ats"`
	RefTypes      []string  `json:"ref_types"`
	Activities    []string  `json:"activities"`
	Amounts       []float64 `json:"amounts"`
	FirstParties  []int64   `json:"first_parties"`
	SecondParties []int64   `json:"second_parties"`
	ContextIds    []int64   `json:"context_ids"`
	ContextTypes  []string  `json:"context_types"`
}

// New rows only; returns the days they fall on so the fold knows
// where to start.
func (q *Queries) InsertLedgerJournalBatch(ctx context.Context, arg InsertLedgerJournalBatchParams) ([]time.Time, error) {
	rows, err := q.db.QueryContext(ctx, insertLedgerJournalBatch,
		arg.OwnerKind,
		arg.OwnerID,
		pq.Array(arg.EntryIds),
		pq.Array(arg.Ats),
		pq.Array(arg.RefTypes),
		pq.Array(arg.Activities),
		pq.Array(arg.Amounts),
		pq.Array(arg.FirstParties),
		pq.Array(arg.SecondParties),
		pq.Array(arg.ContextIds),
		pq.Array(arg.ContextTypes),
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []time.Time
	for rows.Next() {
		var at time.Time
		if err := rows.Scan(&at); err != nil {
			return nil, err
		}
		items = append(items, at)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

