const listTradeItems = `-- name: ListTradeItems :many
SELECT type_id,
       SUM(units)::bigint AS units, SUM(revenue)::float8 AS revenue,
       SUM(cov_units)::bigint AS cov_units, SUM(cov_revenue)::float8 AS cov_revenue,
       SUM(cov_cost)::float8 AS cov_cost, SUM(cov_tax)::float8 AS cov_tax, SUM(broker)::float8 AS broker,
       SUM(gap_before_history)::bigint AS gap_before_history, SUM(gap_ledger_hole)::bigint AS gap_ledger_hole,
       SUM(gap_no_buy)::bigint AS gap_no_buy, SUM(gap_no_tax)::bigint AS gap_no_tax,
       SUM(prev_cov_net)::float8 AS prev_cov_net, SUM(prev_broker)::float8 AS prev_broker,
       SUM(prev_units)::bigint AS prev_units, SUM(prev_cov_units)::bigint AS prev_cov_units
FROM trade_item_window
WHERE owner_kind = $1 AND owner_id = ANY($2::bigint[]) AND win = $3::int
GROUP BY type_id
ORDER BY (SUM(units) > 0 AND SUM(cov_units) >= SUM(units)) DESC,
         SUM(cov_revenue - cov_cost - cov_tax - CASE WHEN $4::bool THEN broker ELSE 0 END) DESC,
         type_id
LIMIT $5::bigint
`

type ListTradeItemsParams struct {
	OwnerKind      string  `json:"owner_kind"`
	OwnerIds       []int64 `json:"owner_ids"`
	Win            int32   `json:"win"`
	BrokerInMargin bool    `json:"broker_in_margin"`
	RowCap         int64   `json:"row_cap"`
}

type ListTradeItemsRow struct {
	TypeID           int64   `json:"type_id"`
	Units            int64   `json:"units"`
	Revenue          float64 `json:"revenue"`
	CovUnits         int64   `json:"cov_units"`
	CovRevenue       float64 `json:"cov_revenue"`
	CovCost          float64 `json:"cov_cost"`
	CovTax           float64 `json:"cov_tax"`
	Broker           float64 `json:"broker"`
	GapBeforeHistory int64   `json:"gap_before_history"`
	GapLedgerHole    int64   `json:"gap_ledger_hole"`
	GapNoBuy         int64   `json:"gap_no_buy"`
	GapNoTax         int64   `json:"gap_no_tax"`
	PrevCovNet       float64 `json:"prev_cov_net"`
	PrevBroker       float64 `json:"prev_broker"`
	PrevUnits        int64   `json:"prev_units"`
	PrevCovUnits     int64   `json:"prev_cov_units"`
}

// The Trading tab: per type over a window for a set of sellers, fully
// covered items first, then by covered margin. Broker fees count in
// the margin unless the player set them aside.
func (q *Queries) ListTradeItems(ctx context.Context, arg ListTradeItemsParams) ([]ListTradeItemsRow, error) {
	rows, err := q.db.QueryContext(ctx, listTradeItems,
		arg.OwnerKind,
		pq.Array(arg.OwnerIds),
		arg.Win,
		arg.BrokerInMargin,
		arg.RowCap,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListTradeItemsRow
	for rows.Next() {
		var i ListTradeItemsRow
		if err := rows.Scan(
			&i.TypeID,
			&i.Units,
			&i.Revenue,
			&i.CovUnits,
			&i.CovRevenue,
			&i.CovCost,
			&i.CovTax,
			&i.Broker,
			&i.GapBeforeHistory,
			&i.GapLedgerHole,
			&i.GapNoBuy,
			&i.GapNoTax,
			&i.PrevCovNet,
			&i.PrevBroker,
			&i.PrevUnits,
			&i.PrevCovUnits,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

