const sumTradeItems = `-- name: SumTradeItems :one
SELECT COALESCE(SUM(units), 0)::bigint AS units, COALESCE(SUM(cov_units), 0)::bigint AS cov_units,
       COALESCE(SUM(cov_revenue - cov_cost - cov_tax), 0)::float8 AS cov_net,
       COALESCE(SUM(broker), 0)::float8 AS broker,
       COALESCE(SUM(prev_cov_net), 0)::float8 AS prev_cov_net, COALESCE(SUM(prev_broker), 0)::float8 AS prev_broker,
       COALESCE(SUM(prev_units), 0)::bigint AS prev_units, COALESCE(SUM(prev_cov_units), 0)::bigint AS prev_cov_units,
       COALESCE(MAX(as_of_day), '')::text AS as_of_day
FROM trade_item_window
WHERE owner_kind = $1 AND owner_id = ANY($2::bigint[]) AND win = $3::int
`

type SumTradeItemsParams struct {
	OwnerKind string  `json:"owner_kind"`
	OwnerIds  []int64 `json:"owner_ids"`
	Win       int32   `json:"win"`
}

type SumTradeItemsRow struct {
	Units        int64   `json:"units"`
	CovUnits     int64   `json:"cov_units"`
	CovNet       float64 `json:"cov_net"`
	Broker       float64 `json:"broker"`
	PrevCovNet   float64 `json:"prev_cov_net"`
	PrevBroker   float64 `json:"prev_broker"`
	PrevUnits    int64   `json:"prev_units"`
	PrevCovUnits int64   `json:"prev_cov_units"`
	AsOfDay      string  `json:"as_of_day"`
}

// The Trading tab's header: the same figures over every type.
func (q *Queries) SumTradeItems(ctx context.Context, arg SumTradeItemsParams) (SumTradeItemsRow, error) {
	row := q.db.QueryRowContext(ctx, sumTradeItems, arg.OwnerKind, pq.Array(arg.OwnerIds), arg.Win)
	var i SumTradeItemsRow
	err := row.Scan(
		&i.Units,
		&i.CovUnits,
		&i.CovNet,
		&i.Broker,
		&i.PrevCovNet,
		&i.PrevBroker,
		&i.PrevUnits,
		&i.PrevCovUnits,
		&i.AsOfDay,
	)
	return i, err
}

const sumTradingFeesFrom = `-- name: SumTradingFeesFrom :one
SELECT COALESCE(SUM(CASE WHEN ref_type = 'transaction_tax' THEN -amount ELSE 0 END), 0)::float8 AS sales_tax,
       COALESCE(SUM(CASE WHEN ref_type = 'brokers_fee' THEN -amount ELSE 0 END), 0)::float8 AS broker_fees
FROM ledger_journal
WHERE owner_kind = $1 AND owner_id = ANY($2::bigint[])
  AND at >= $3::timestamptz AND activity = 'trading'
`

